This version stores the actual LCS string in each DP cell instead of only its length. After getting that common sequence, I walk through it and copy characters from each input until the next LCS character is reached.

It is easy to follow, but storing full strings makes it heavier than an integer table. The LCS cells are still enough to keep the shared characters from being copied twice.

```go
func shortestCommonSupersequence(str1 string, str2 string) string {
	n := len(str1)
	m := len(str2)
	lcs := make([][]string, n+1)
	for i := range lcs {
		lcs[i] = make([]string, m+1)
	}

	for i := 1; i <= n; i++ {
		for j := 1; j <= m; j++ {
			if str1[i-1] == str2[j-1] {
				lcs[i][j] = lcs[i-1][j-1] + string(str1[i-1])
			} else if len(lcs[i-1][j]) >= len(lcs[i][j-1]) {
				lcs[i][j] = lcs[i-1][j]
			} else {
				lcs[i][j] = lcs[i][j-1]
			}
		}
	}

	common := lcs[n][m]
	answer := make([]byte, 0, n+m-len(common))
	i := 0
	j := 0

	for k := 0; k < len(common); k++ {
		for str1[i] != common[k] {
			answer = append(answer, str1[i])
			i++
		}
		for str2[j] != common[k] {
			answer = append(answer, str2[j])
			j++
		}
		answer = append(answer, common[k])
		i++
		j++
	}

	answer = append(answer, str1[i:]...)
	answer = append(answer, str2[j:]...)
	return string(answer)
}
```

Time complexity: `O(n * m * (n + m))` because each table entry may copy a string.
Space complexity: `O(n * m * (n + m))` for the string table.

Here `dp[i][j]` means the shortest length needed for the suffixes starting at `i` and `j`. This makes the reconstruction go from left to right, so there is no final reverse step.

When the current characters match, one character is enough. Otherwise, I choose the smaller of taking from `str1` or taking from `str2`. If the lengths tie, either choice still gives a valid shortest result.

```java
class Solution {
    public String shortestCommonSupersequence(String str1, String str2) {
        int n = str1.length();
        int m = str2.length();
        int[][] dp = new int[n + 1][m + 1];

        for (int i = n; i >= 0; --i) {
            dp[i][m] = n - i;
        }
        for (int j = m; j >= 0; --j) {
            dp[n][j] = m - j;
        }

        for (int i = n - 1; i >= 0; --i) {
            for (int j = m - 1; j >= 0; --j) {
                if (str1.charAt(i) == str2.charAt(j)) {
                    dp[i][j] = 1 + dp[i + 1][j + 1];
                } else {
                    dp[i][j] = 1 + Math.min(dp[i + 1][j], dp[i][j + 1]);
                }
            }
        }

        StringBuilder answer = new StringBuilder();
        int i = 0;
        int j = 0;

        while (i < n && j < m) {
            if (str1.charAt(i) == str2.charAt(j)) {
                answer.append(str1.charAt(i));
                ++i;
                ++j;
            } else if (dp[i + 1][j] <= dp[i][j + 1]) {
                answer.append(str1.charAt(i));
                ++i;
            } else {
                answer.append(str2.charAt(j));
                ++j;
            }
        }

        while (i < n) {
            answer.append(str1.charAt(i++));
        }
        while (j < m) {
            answer.append(str2.charAt(j++));
        }

        return answer.toString();
    }
}
```

Time complexity: `O(n * m)`.
Space complexity: `O(n * m)`, not counting the returned string.

This is the direct recursive version. At each mismatch, it tries putting the next character from either string and returns the shorter result. A matching character is added once.

Dry run with `str1 = "a"` and `str2 = "b"`: one branch creates `"ab"` and the other creates `"ba"`. Both have the minimum length, so returning either one is fine.

This is useful for seeing the recurrence, but it repeats the same states many times and will become slow for larger strings.

```cpp
#include <bits/stdc++.h>
using namespace std;

class Solution {
    string solve(const string& str1, const string& str2, int i, int j) {
        if (i == static_cast<int>(str1.size())) {
            return str2.substr(j);
        }
        if (j == static_cast<int>(str2.size())) {
            return str1.substr(i);
        }

        if (str1[i] == str2[j]) {
            return string(1, str1[i]) + solve(str1, str2, i + 1, j + 1);
        }

        string fromFirst = string(1, str1[i]) + solve(str1, str2, i + 1, j);
        string fromSecond = string(1, str2[j]) + solve(str1, str2, i, j + 1);

        if (fromFirst.size() <= fromSecond.size()) {
            return fromFirst;
        }
        return fromSecond;
    }

public:
    string shortestCommonSupersequence(string str1, string str2) {
        return solve(str1, str2, 0, 0);
    }
};
```

Empty input is handled before accessing either character. For instance, if `str1` is empty, the function immediately returns `str2`.

Time complexity: exponential in `n + m`, with extra string-copying cost at each branch.
Space complexity: `O(n + m)` recursion depth, plus temporary strings created by the calls.

The shared characters should be added only once. I first store the LCS length for every pair of prefixes. During backtracking, equal characters are taken once, and for different characters I move toward the larger LCS value.

Dry run for `str1 = "abac"` and `str2 = "cab"`: the table gives an LCS length of `2`. Backtracking can collect `c`, `a`, `b`, `a`, and `c`, producing `"cabac"`.

```cpp
#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    string shortestCommonSupersequence(string str1, string str2) {
        int n = str1.size();
        int m = str2.size();
        vector<vector<int>> lcs(n + 1, vector<int>(m + 1, 0));

        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= m; ++j) {
                if (str1[i - 1] == str2[j - 1]) {
                    lcs[i][j] = lcs[i - 1][j - 1] + 1;
                } else {
                    lcs[i][j] = max(lcs[i - 1][j], lcs[i][j - 1]);
                }
            }
        }

        string answer;
        int i = n;
        int j = m;

        while (i > 0 && j > 0) {
            if (str1[i - 1] == str2[j - 1]) {
                answer.push_back(str1[i - 1]);
                --i;
                --j;
            } else if (lcs[i - 1][j] > lcs[i][j - 1]) {
                answer.push_back(str1[i - 1]);
                --i;
            } else {
                answer.push_back(str2[j - 1]);
                --j;
            }
        }

        while (i > 0) {
            answer.push_back(str1[i - 1]);
            --i;
        }
        while (j > 0) {
            answer.push_back(str2[j - 1]);
            --j;
        }

        reverse(answer.begin(), answer.end());
        return answer;
    }
};
```

Time complexity: `O(n * m)`.
Space complexity: `O(n * m)` for the table and `O(n + m)` for the answer.

I used recursion on the two remaining suffixes, but saved each result in `memo`. A state `(i, j)` returns the actual shortest string for `str1[i:]` and `str2[j:]`.

For example, with `"abac"` and `"cab"`, the recursion first compares `a` and `c`, tries both possible next moves, and keeps the shorter result. Equal letters are handled in one move because adding them twice would be unnecessary.

```python
class Solution:
    def shortestCommonSupersequence(self, str1: str, str2: str) -> str:
        memo = {}
        n = len(str1)
        m = len(str2)

        def build(i: int, j: int) -> str:
            if i == n:
                return str2[j:]
            if j == m:
                return str1[i:]
            if (i, j) in memo:
                return memo[(i, j)]

            if str1[i] == str2[j]:
                result = str1[i] + build(i + 1, j + 1)
            else:
                take_first = str1[i] + build(i + 1, j)
                take_second = str2[j] + build(i, j + 1)
                result = take_first if len(take_first) <= len(take_second) else take_second

            memo[(i, j)] = result
            return result

        return build(0, 0)
```

The empty-string cases are covered directly: if one input is empty, the other input is already the answer.

Time complexity: `O(n * m * (n + m))` because states store strings and string creation can cost up to `O(n + m)`.
Space complexity: `O(n * m * (n + m))` for the memoized strings, plus recursion stack space.

